INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(421310, 38183, 9854, '<td valign="top">Beautiful mirror effect! Is this a Turkish bath house, or an abandoned building with faulty drainage? :) Minor comment: the lighting at the top washes out the details of the ornate ceiling. It would have worked, too, had the wash out been made to look intentional to achieve a dreamy cast to your foto.</td>', 'Beautiful mirror effect! Is this a Turkish bath house, or an abandoned building with faulty drainage? :) Minor comment: the lighting at the top washes out the details of the ornate ceiling. It would have worked, too, had the wash out been made to look intentional to achieve a dreamy cast to your foto.', '2003-09-17 04:48:19.000000', NULL, 1),
(421313, 37295, 9422, '<td valign="top">The symmetry of the photograph makes the image look peaceful. I also enjoy the conflicting colors of the white and red jacket and with the water in the background. Good photo!</td>', 'The symmetry of the photograph makes the image look peaceful. I also enjoy the conflicting colors of the white and red jacket and with the water in the background. Good photo!', '2003-09-17 04:48:46.000000', NULL, 1),
