INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(422367, 38056, 4224, '<td valign="top">i love the colors of the brown leaf and the background, however the border really distracts me from what i want to be looking at.</td>', 'i love the colors of the brown leaf and the background, however the border really distracts me from what i want to be looking at.', '2003-09-17 21:08:45.000000', NULL, 1),
(422368, 38151, 11793, '<td valign="top">hehe<br/>true enough<br/></td>', 'hehetrue enough', '2003-09-17 21:09:15.000000', NULL, 1),
(422369, 38120, 8522, '<td valign="top">Life is like a Frisbee?!? I think that''s the stretchiest analogy I''ve come across for life yet. That''s worse than a box of chocolates. The photo is pretty cluttered, there''s too much background that distracts from the subject. 4</td>', 'Life is like a Frisbee?!? I think that''s the stretchiest analogy I''ve come across for life yet. That''s worse than a box of chocolates. The photo is pretty cluttered, there''s too much background that distracts from the subject. 4', '2003-09-17 21:09:17.000000', NULL, 1),
(422370, 37867, 11793, '<td valign="top">out of focus<br/></td>', 'out of focus', '2003-09-17 21:09:37.000000', NULL, 1),
(422372, 37753, 4224, '<td valign="top">i find myself staring at his chest hair much more than thinking about how hard his life is.  did he have to sell his clothes?  ^^;  stil, good portrait.  nice framing, although not sure about cutting off the tattoo.</td>', 'i find myself staring at his chest hair much more than thinking about how hard his life is.  did he have to sell his clothes?  ^^;  stil, good portrait.  nice framing, although not sure about cutting off the tattoo.', '2003-09-17 21:12:33.000000', NULL, 1),
(422374, 38092, 4224, '<td valign="top">very surreal, nice colors</td>', 'very surreal, nice colors', '2003-09-17 21:13:08.000000', NULL, 1),
(422375, 37811, 4224, '<td valign="top">lovely shot, it draws me in.</td>', 'lovely shot, it draws me in.', '2003-09-17 21:13:34.000000', NULL, 1),
(422377, 37283, 8522, '<td valign="top">A Bibble is a very unique thing indeed!<br/>Shame about your colour cast, did you set the white balance correctly?</td>', 'A Bibble is a very unique thing indeed!Shame about your colour cast, did you set the white balance correctly?', '2003-09-17 21:16:23.000000', NULL, 1),
(422381, 37998, 12151, '<td valign="top">reminds me of a drug company advertisement, like allegra or something.  other than that shady connotation, this would otherwise be a very high scoring photo.</td>', 'reminds me of a drug company advertisement, like allegra or something.  other than that shady connotation, this would otherwise be a very high scoring photo.', '2003-09-17 21:24:22.000000', NULL, 1),
(422382, 37917, 11495, '<td valign="top">..but?</td>', '..but?', '2003-09-17 21:24:49.000000', NULL, 1),
(422383, 38090, 11432, '<td valign="top">Good Snapshot, the green is a little distracting. Nice Depth of Field.</td>', 'Good Snapshot, the green is a little distracting. Nice Depth of Field.', '2003-09-17 21:24:52.000000', NULL, 1),
(422386, 37498, 8522, '<td valign="top">This looks more like a toothpaste commercial!<br/>Seriously though, great picture... perhaps just a little on the cheesy side for my taste, Great lighting, very photogenic subjects. Not sure if it really hits as an interpretation of life though. 7</td>', 'This looks more like a toothpaste commercial!Seriously though, great picture... perhaps just a little on the cheesy side for my taste, Great lighting, very photogenic subjects. Not sure if it really hits as an interpretation of life though. 7', '2003-09-17 21:27:20.000000', NULL, 1),
(422389, 37917, 8522, '<td valign="top">Why the ''but''? Small point, but please use a spellchecker for your titles. Wonderful photo, great composition, very effective use of dof as a compositional device. Great lighting. 8</td>', 'Why the ''but''? Small point, but please use a spellchecker for your titles. Wonderful photo, great composition, very effective use of dof as a compositional device. Great lighting. 8', '2003-09-17 21:29:36.000000', NULL, 1),
(422390, 38053, 10510, '<td valign="top">Too freaking wierd and scary.   Reminds me of a Kiefer Sutherland movie - what was it - Highway?   I don''t know what the movie title is exactly, but this is a very unique photo.  I''m giving it a 10.</td>', 'Too freaking wierd and scary.   Reminds me of a Kiefer Sutherland movie - what was it - Highway?   I don''t know what the movie title is exactly, but this is a very unique photo.  I''m giving it a 10.', '2003-09-17 21:29:55.000000', NULL, 1),
(422393, 37490, 11495, '<td valign="top">Pepsi is your life? Uhmmm....</td>', 'Pepsi is your life? Uhmmm....', '2003-09-17 21:32:21.000000', NULL, 1),
(422394, 38170, 10510, '<td valign="top">Great photo!  I love that the little girl in the front left is looking back at you like she is pretending to hold a camera.  She will probably grow up to be a very creative person.</td>', 'Great photo!  I love that the little girl in the front left is looking back at you like she is pretending to hold a camera.  She will probably grow up to be a very creative person.', '2003-09-17 21:32:27.000000', NULL, 1),
(422396, 38020, 8522, '<td valign="top">Fantastic concept and execution. The roots in water are excellent. Not entirely sure about the effectiveness of the sky, but a darned good shot anyway. HOWEVER, I can''t stand your border, which I''m going to have to knock off a couple of points for. I cannot concentrate on the photo with that huge frame pulling my eye away, and your photo has been made far too small. Shame. 7</td>', 'Fantastic concept and execution. The roots in water are excellent. Not entirely sure about the effectiveness of the sky, but a darned good shot anyway. HOWEVER, I can''t stand your border, which I''m going to have to knock off a couple of points for. I cannot concentrate on the photo with that huge frame pulling my eye away, and your photo has been made far too small. Shame. 7', '2003-09-17 21:34:09.000000', NULL, 1),
(422398, 38015, 12151, '<td valign="top">This seems in between a poster and a photograph.  I''d like this one more if it were posterized more, or looked almost drawn and smooth at the same time.</td>', 'This seems in between a poster and a photograph.  I''d like this one more if it were posterized more, or looked almost drawn and smooth at the same time.', '2003-09-17 21:34:36.000000', NULL, 1),
(422399, 37942, 11096, '<td valign="top">It a little dark but I like the concept.</td>', 'It a little dark but I like the concept.', '2003-09-17 21:34:49.000000', NULL, 1),
(422400, 38114, 10510, '<td valign="top">Usually someone is pushing the wheelchair.  Great photo.</td>', 'Usually someone is pushing the wheelchair.  Great photo.', '2003-09-17 21:35:36.000000', NULL, 1),
(422401, 38090, 10510, '<td valign="top">Such a beautifufl child.  Good luck to you as he grows older, he may be a handful.  And a heartbreaker I am sure!</td>', 'Such a beautifufl child.  Good luck to you as he grows older, he may be a handful.  And a heartbreaker I am sure!', '2003-09-17 21:37:13.000000', NULL, 1),
(422403, 38168, 11096, '<td valign="top">Crop a little of the water beyond the splash.  There isn''t much detail there and it detracts from the overall picture.  But I like it a lot</td>', 'Crop a little of the water beyond the splash.  There isn''t much detail there and it detracts from the overall picture.  But I like it a lot', '2003-09-17 21:38:22.000000', NULL, 1),
(422404, 37611, 8522, '<td valign="top">Oh WOW what an excellent idea for this challenge. I wish your picture was larger though, and this is a rare occasion when I feel a frame could really have helped here. I think that a landscape orientation crop with  perhaps a timeline containing events in a person''s life could have helped. The tall crop here emphasises the height of the flame, rather than the horizontal movement. 6</td>', 'Oh WOW what an excellent idea for this challenge. I wish your picture was larger though, and this is a rare occasion when I feel a frame could really have helped here. I think that a landscape orientation crop with  perhaps a timeline containing events in a person''s life could have helped. The tall crop here emphasises the height of the flame, rather than the horizontal movement. 6', '2003-09-17 21:38:47.000000', NULL, 1),
(422406, 38056, 8522, '<td valign="top">Dear God, where has that enorous intrusive border come from? An interesting abstract, but hard to focus on it as opposed to the border. NeatImage could have done wonders for the noise levels in the shot. Without border, score possibly 7. With border: 5</td>', 'Dear God, where has that enorous intrusive border come from? An interesting abstract, but hard to focus on it as opposed to the border. NeatImage could have done wonders for the noise levels in the shot. Without border, score possibly 7. With border: 5', '2003-09-17 21:40:49.000000', NULL, 1),
(422407, 37867, 11495, '<td valign="top">Shame too large pixels.</td>', 'Shame too large pixels.', '2003-09-17 21:41:06.000000', NULL, 1),
(422408, 37360, 10510, '<td valign="top">Party on...  Hey - I think that guy in the lower right is my brother-in-law!  Great picture, but wait till I show this to my sister.  Haha.</td>', 'Party on...  Hey - I think that guy in the lower right is my brother-in-law!  Great picture, but wait till I show this to my sister.  Haha.', '2003-09-17 21:41:16.000000', NULL, 1),
(422409, 38090, 8522, '<td valign="top">Superb portrait, there''s something about his eyes which are full of life, and seems a bit beyond his years, so fits the challenge nicely. Great crop. Nice lighting, but a little on the green side for my liking. 8</td>', 'Superb portrait, there''s something about his eyes which are full of life, and seems a bit beyond his years, so fits the challenge nicely. Great crop. Nice lighting, but a little on the green side for my liking. 8', '2003-09-17 21:42:53.000000', NULL, 1),
