(422412, 37721, 11495, '<td valign="top">good shot but how it is pertinent with the life theme?</td>', 'good shot but how it is pertinent with the life theme?', '2003-09-17 21:44:27.000000', NULL, 1),
(422414, 38090, 11096, '<td valign="top">Seems to have a greenish tint to his skin. But I love the look on his face.</td>', 'Seems to have a greenish tint to his skin. But I love the look on his face.', '2003-09-17 21:44:47.000000', NULL, 1),
(422418, 37295, 10510, '<td valign="top">Good concept, but wish they were more connected with each other.  Looks like they are each thinking about what could have been instead of what is.  Top ten maybe.</td>', 'Good concept, but wish they were more connected with each other.  Looks like they are each thinking about what could have been instead of what is.  Top ten maybe.', '2003-09-17 21:47:44.000000', NULL, 1),
