(423479, 37659, 11495, '<td valign="top">Good composition but shame for focus....</td>', 'Good composition but shame for focus....', '2003-09-18 19:27:33.000000', NULL, 1),
(423499, 37695, 2567, '<td valign="top">Refreshing concept - good composition and coloring.  Good luck.</td>', 'Refreshing concept - good composition and coloring.  Good luck.', '2003-09-18 20:06:44.000000', NULL, 1),
(423502, 37746, 1379, '<td valign="top">I hope this animal is in the wild, truly experiencing joy and freedom.  Otherwise, this swim is probably just one of the few ways to interrupt the monotony of captivity.  The poor dear.</td>', 'I hope this animal is in the wild, truly experiencing joy and freedom.  Otherwise, this swim is probably just one of the few ways to interrupt the monotony of captivity.  The poor dear.', '2003-09-18 20:10:12.000000', NULL, 1),
(423505, 37644, 1379, '<td valign="top">Heh....  I get the Mary Engelbreit reference.  Funny!</td>', 'Heh....  I get the Mary Engelbreit reference.  Funny!', '2003-09-18 20:21:16.000000', NULL, 1),
(423507, 38029, 4411, '<td valign="top">Awesome shot. Great use of DoF, especially the blurred out circles of light. The subdued colours are great.</td>', 'Awesome shot. Great use of DoF, especially the blurred out circles of light. The subdued colours are great.', '2003-09-18 20:26:49.000000', NULL, 1),
(423509, 38097, 4411, '<td valign="top">A bit too bright, and too centered on the main subject. A good idea for the challenge and no problems that a spot of editing couldn''t sort out.</td>', 'A bit too bright, and too centered on the main subject. A good idea for the challenge and no problems that a spot of editing couldn''t sort out.', '2003-09-18 20:28:07.000000', NULL, 1),
(423510, 38085, 4411, '<td valign="top">Nicely composed and exposed, I like the high-key feel of this. Looks like there''s some fringing around the brightly lit area though.</td>', 'Nicely composed and exposed, I like the high-key feel of this. Looks like there''s some fringing around the brightly lit area though.', '2003-09-18 20:31:35.000000', NULL, 1),
(423511, 37386, 10608, '<td valign="top">This is my highest score so far. I love this shot mainly for the blend of colors from browns to gold. I think its great!</td>', 'This is my highest score so far. I love this shot mainly for the blend of colors from browns to gold. I think its great!', '2003-09-18 20:31:42.000000', NULL, 1),
(423512, 37942, 4411, '<td valign="top">Nice. The ''star'' on the flame is very effective.</td>', 'Nice. The ''star'' on the flame is very effective.', '2003-09-18 20:33:17.000000', NULL, 1),
(423522, 37577, 4411, '<td valign="top">I''m struggling to work out your interpretation here. This is good - your photo is making me stop and think. Ignoring the title I can start creating my own interpretations. A good shot too - well composed and focused.</td>', 'I''m struggling to work out your interpretation here. This is good - your photo is making me stop and think. Ignoring the title I can start creating my own interpretations. A good shot too - well composed and focused.', '2003-09-18 20:54:23.000000', NULL, 1),
(423525, 37324, 10918, '<td valign="top">More Effective in black and white.</td>', 'More Effective in black and white.', '2003-09-18 20:56:46.000000', NULL, 1),
(423526, 38013, 4411, '<td valign="top">Excellent. Not too sure about the title ; ) but it gets across the interpretation I suppose.<br/>I like the blown out Moon, it adds atmosphere to the shot more than a correctly exposed Moon would. Is that Mars in there too?</td>', 'Excellent. Not too sure about the title ; ) but it gets across the interpretation I suppose.I like the blown out Moon, it adds atmosphere to the shot more than a correctly exposed Moon would. Is that Mars in there too?', '2003-09-18 20:57:27.000000', NULL, 1),
