(424325, 37980, 11111, '<td valign="top">Nice sharp shot! The dog''s expression says it all!</td>', 'Nice sharp shot! The dog''s expression says it all!', '2003-09-19 22:12:43.000000', NULL, 1),
(424327, 37341, 11111, '<td valign="top">Beautiful, simple composition. Good subject matter. Appears to be somewhat washed out - but that may just be my monitor.</td>', 'Beautiful, simple composition. Good subject matter. Appears to be somewhat washed out - but that may just be my monitor.', '2003-09-19 22:13:50.000000', NULL, 1),
