(424869, 37963, 10402, '<td valign="top">I love the variety of colors here, and the black and white colander is a nice touch. Great still life.</td>', 'I love the variety of colors here, and the black and white colander is a nice touch. Great still life.', '2003-09-21 00:37:57.000000', NULL, 1),
(424870, 37264, 10402, '<td valign="top">I like the trees on just one side casting shadows over the path. And the fact you can''t see very far along the path is apropos.</td>', 'I like the trees on just one side casting shadows over the path. And the fact you can''t see very far along the path is apropos.', '2003-09-21 00:41:06.000000', NULL, 1),
