(425250, 37473, 10402, '<td valign="top">Using your hand as the background is a subtle clue to the small size of this critter. Nice focus and composition.</td>', 'Using your hand as the background is a subtle clue to the small size of this critter. Nice focus and composition.', '2003-09-21 21:47:46.000000', NULL, 1),
(425253, 38135, 10263, '<td valign="top">He is so beautiful. I can almost smell the sweet baby scent from here :) It sure brings tears to this grammy''s eyes.</td>', 'He is so beautiful. I can almost smell the sweet baby scent from here :) It sure brings tears to this grammy''s eyes.', '2003-09-21 21:53:00.000000', NULL, 1),
(425270, 38065, 10263, '<td valign="top">This is wonderful. I love his face. My only 10 in this challenge</td>', 'This is wonderful. I love his face. My only 10 in this challenge', '2003-09-21 22:25:23.000000', NULL, 1),
(425274, 37774, 10263, '<td valign="top">Excellent, excellent photo. Great stop-action. A little dark but still gets a 9 from me.</td>', 'Excellent, excellent photo. Great stop-action. A little dark but still gets a 9 from me.', '2003-09-21 22:30:46.000000', NULL, 1),
(425280, 38189, 258, '<td valign="top">Does the image need rotated?</td>', 'Does the image need rotated?', '2003-09-21 22:37:14.000000', NULL, 1),
(425334, 37893, 6668, '<td valign="top">Beautiful, too bad for the sun spot.</td>', 'Beautiful, too bad for the sun spot.', '2003-09-22 00:57:32.000000', NULL, 1),
(425337, 37734, 6668, '<td valign="top">Nice shot, I like the black and white, but photo seems a bit to small.</td>', 'Nice shot, I like the black and white, but photo seems a bit to small.', '2003-09-22 00:58:59.000000', NULL, 1),
(425338, 38074, 6668, '<td valign="top">Precious baby!</td>', 'Precious baby!', '2003-09-22 00:59:40.000000', NULL, 1),
(425339, 38066, 6668, '<td valign="top">photo seems a bit grainy.</td>', 'photo seems a bit grainy.', '2003-09-22 01:00:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(425505, 38193, 9523, '<td valign="top">It''s cute and all, but somehow it has a doctored feel to it, as if designed specifically for a Halmark card or something. It doesn''t look real...</td>', 'It''s cute and all, but somehow it has a doctored feel to it, as if designed specifically for a Halmark card or something. It doesn''t look real...', '2003-09-22 02:22:10.000000', NULL, 1),
(425509, 37776, 9523, '<td valign="top">Could''ve... ahem, cleaned her off a bit before shooting this. I''m sure it''s just dirt, but it''s not too visually pleasing. Other than that, it''s great.</td>', 'Could''ve... ahem, cleaned her off a bit before shooting this. I''m sure it''s just dirt, but it''s not too visually pleasing. Other than that, it''s great.', '2003-09-22 02:24:13.000000', NULL, 1),
(425510, 37264, 11209, '<td valign="top">This path is going up?</td>', 'This path is going up?', '2003-09-22 02:24:33.000000', NULL, 1),
(425513, 37271, 9523, '<td valign="top">What did poor Mr. Elephant and Frosty ever do you to? Hah. Pity we can''t see her full expression.</td>', 'What did poor Mr. Elephant and Frosty ever do you to? Hah. Pity we can''t see her full expression.', '2003-09-22 02:26:10.000000', NULL, 1),
(425515, 37540, 9523, '<td valign="top">Wonderful. :D</td>', 'Wonderful. :D', '2003-09-22 02:27:02.000000', NULL, 1),
(425524, 37490, 12379, '<td valign="top">Could use a bit more contrast to pop the whites.....j²</td>', 'Could use a bit more contrast to pop the whites.....j²', '2003-09-22 02:33:13.000000', NULL, 1),
(425526, 38028, 12379, '<td valign="top">too funny!!  j²</td>', 'too funny!!  j²', '2003-09-22 02:34:48.000000', NULL, 1),
(425528, 37978, 9523, '<td valign="top">Framing could be better (to get all her leg and to hide the guy in the background), but their faces are nice and innocent. Enjoy their getting along while it lasts, hah.</td>', 'Framing could be better (to get all her leg and to hide the guy in the background), but their faces are nice and innocent. Enjoy their getting along while it lasts, hah.', '2003-09-22 02:35:47.000000', NULL, 1),
(425529, 37952, 12379, '<td valign="top">beautiful greens, especially like the reflections!</td>', 'beautiful greens, especially like the reflections!', '2003-09-22 02:36:03.000000', NULL, 1),
(425535, 38175, 12379, '<td valign="top">Thumbnail looked a bit freaky, but this is so cool when opened up!  j²</td>', 'Thumbnail looked a bit freaky, but this is so cool when opened up!  j²', '2003-09-22 02:39:39.000000', NULL, 1),
(425537, 37730, 9523, '<td valign="top">The selective greyscale doesn''t work well in this photograph. If you''re going to leave a spec of blue and violet, you might as well just leave the green, too.  Otherwise, it''s like "Pleasantville" gone awry.</td>', 'The selective greyscale doesn''t work well in this photograph. If you''re going to leave a spec of blue and violet, you might as well just leave the green, too.  Otherwise, it''s like "Pleasantville" gone awry.', '2003-09-22 02:40:41.000000', NULL, 1),
(425542, 37498, 9523, '<td valign="top">They''re just friends, eh? ;)<br/>I don''t know where the fourth person is looking, but it doesn''t take away all that much from the shot.</td>', 'They''re just friends, eh? ;)I don''t know where the fourth person is looking, but it doesn''t take away all that much from the shot.', '2003-09-22 02:42:50.000000', NULL, 1),
(425545, 37973, 9523, '<td valign="top">Clinton looks doctored to me... I can''t decide. I don''t understand this, though. Does the man at the podium have something to do with life or abortion or anything like that?</td>', 'Clinton looks doctored to me... I can''t decide. I don''t understand this, though. Does the man at the podium have something to do with life or abortion or anything like that?', '2003-09-22 02:45:57.000000', NULL, 1),
(425561, 37761, 7689, '<td valign="top">can''t really relate your title to the picture but nice shot though.</td>', 'can''t really relate your title to the picture but nice shot though.', '2003-09-22 03:13:21.000000', NULL, 1),
(425562, 38154, 7689, '<td valign="top">Beautiful composition and shot... the lighting is excellent. You get my one of the two 10''s. Please share the picture details and the lighting info for this shot.</td>', 'Beautiful composition and shot... the lighting is excellent. You get my one of the two 10''s. Please share the picture details and the lighting info for this shot.', '2003-09-22 03:19:20.000000', NULL, 1),
(425564, 38106, 7689, '<td valign="top">seems like a shot from an airplane...?  looks very grainy and dull...</td>', 'seems like a shot from an airplane...?  looks very grainy and dull...', '2003-09-22 03:20:10.000000', NULL, 1),
(425566, 38080, 7689, '<td valign="top">Frame relly does nothing to the picture... infact it is spoiling it... good composition though.</td>', 'Frame relly does nothing to the picture... infact it is spoiling it... good composition though.', '2003-09-22 03:22:12.000000', NULL, 1),
(425613, 37912, 7689, '<td valign="top">Good composition... the ''eye'' on the tree is very appealing..</td>', 'Good composition... the ''eye'' on the tree is very appealing..', '2003-09-22 04:50:24.000000', NULL, 1),
(425614, 38168, 7689, '<td valign="top">a little overexposed otherwise beautiful timing and composition.</td>', 'a little overexposed otherwise beautiful timing and composition.', '2003-09-22 04:51:35.000000', NULL, 1),
(425616, 37690, 7689, '<td valign="top">nice colors and capture.</td>', 'nice colors and capture.', '2003-09-22 04:52:24.000000', NULL, 1),
(425617, 37722, 7689, '<td valign="top">image is not very sharp and the flash light in the eye is distracting.</td>', 'image is not very sharp and the flash light in the eye is distracting.', '2003-09-22 04:53:09.000000', NULL, 1),
(425618, 38082, 10084, '<td valign="top">Incredible details in the hands holding the marble. The beautiful yellow marble and its great reflection in the hand really make it pop out of the picture. The depth of field gives the piece a lot of interest. "10"</td>', 'Incredible details in the hands holding the marble. The beautiful yellow marble and its great reflection in the hand really make it pop out of the picture. The depth of field gives the piece a lot of interest. "10"', '2003-09-22 04:54:06.000000', NULL, 1),
(425619, 38135, 10084, '<td valign="top">Beautifully composed shot. Great shadows and reflections makes the baby pop out of the picture.  Focusing is really good. You can see some details in the baby skin. Such a sweet picture. Nothing less then "10"</td>', 'Beautifully composed shot. Great shadows and reflections makes the baby pop out of the picture.  Focusing is really good. You can see some details in the baby skin. Such a sweet picture. Nothing less then "10"', '2003-09-22 04:56:20.000000', NULL, 1),
(425620, 37714, 7689, '<td valign="top">nice shot.. a little overexposed though.</td>', 'nice shot.. a little overexposed though.', '2003-09-22 04:59:02.000000', NULL, 1),
(425621, 38156, 7689, '<td valign="top">very beautiful composition... a little off focus but I guess you did your best.</td>', 'very beautiful composition... a little off focus but I guess you did your best.', '2003-09-22 04:59:48.000000', NULL, 1),
(425622, 37805, 7689, '<td valign="top">the fence wire in the picture is distracting..</td>', 'the fence wire in the picture is distracting..', '2003-09-22 05:00:40.000000', NULL, 1),
(425623, 37939, 7689, '<td valign="top">could have done without the flowers... they are out of focus.</td>', 'could have done without the flowers... they are out of focus.', '2003-09-22 05:01:28.000000', NULL, 1),
(425631, 37360, 7689, '<td valign="top">too much clutter... image is very distracting</td>', 'too much clutter... image is very distracting', '2003-09-22 05:14:59.000000', NULL, 1),
(425632, 37529, 7531, '<td valign="top">This would have been my favourite for this challenge, I am sure that you have been told already it is way too light, why? you could have post edited it darker, is your monitor dark???</td>', 'This would have been my favourite for this challenge, I am sure that you have been told already it is way too light, why? you could have post edited it darker, is your monitor dark???', '2003-09-22 05:49:01.000000', NULL, 1),
(425634, 37959, 12408, '<td valign="top">The image of two sisters (or perhaps Mother and Daughter) holding the newborn is classic but always touching.</td>', 'The image of two sisters (or perhaps Mother and Daughter) holding the newborn is classic but always touching.', '2003-09-22 06:37:26.000000', NULL, 1),
(425635, 37502, 12408, '<td valign="top">This is more like Death than Life - and on top of which it''s a fairly lousy picture!</td>', 'This is more like Death than Life - and on top of which it''s a fairly lousy picture!', '2003-09-22 06:38:32.000000', NULL, 1),
(425637, 38013, 12408, '<td valign="top">A clever picture, very well realised, but having very little to do with the subject of Life as we know it - or does it refer to Life in the Fast Lane?</td>', 'A clever picture, very well realised, but having very little to do with the subject of Life as we know it - or does it refer to Life in the Fast Lane?', '2003-09-22 06:41:46.000000', NULL, 1),
(425638, 38089, 12408, '<td valign="top">A cool Mardi Gras snap - lots of life but the Photoshop ''feathering'' has gone over the top!</td>', 'A cool Mardi Gras snap - lots of life but the Photoshop ''feathering'' has gone over the top!', '2003-09-22 06:43:03.000000', NULL, 1),
(425639, 37916, 12408, '<td valign="top">The shallow depth of field has rather taken the edge off this picture - a hard one to get - and it really belongs in a challenge about Insects or Macros or something - not much Life in this insect.</td>', 'The shallow depth of field has rather taken the edge off this picture - a hard one to get - and it really belongs in a challenge about Insects or Macros or something - not much Life in this insect.', '2003-09-22 06:44:29.000000', NULL, 1),
(425640, 38172, 12408, '<td valign="top">Someone will have to tell me what this picture is of - after an explosion?</td>', 'Someone will have to tell me what this picture is of - after an explosion?', '2003-09-22 06:45:35.000000', NULL, 1),
(425641, 37500, 12408, '<td valign="top">does this fellow live in the box? is this his life?</td>', 'does this fellow live in the box? is this his life?', '2003-09-22 06:46:02.000000', NULL, 1),
(425643, 37896, 12408, '<td valign="top">Hardly belongs in a challenge regarding Life - more, perhaps in a Zoo.</td>', 'Hardly belongs in a challenge regarding Life - more, perhaps in a Zoo.', '2003-09-22 06:47:23.000000', NULL, 1),
(425647, 37734, 12408, '<td valign="top">A good one - we see this kind of sign everywhere these days and it does pertain to the subject of Life - but I would have straightened out the horizon.</td>', 'A good one - we see this kind of sign everywhere these days and it does pertain to the subject of Life - but I would have straightened out the horizon.', '2003-09-22 06:54:05.000000', NULL, 1),
(425649, 37809, 12408, '<td valign="top">well, Life is featured on the pack - but that''s all it has to do with the real subject</td>', 'well, Life is featured on the pack - but that''s all it has to do with the real subject', '2003-09-22 06:54:59.000000', NULL, 1),
(425650, 37762, 12408, '<td valign="top">No - Death appears to go on in this picture, despite the flag. Cemeteries do not usually express Life.</td>', 'No - Death appears to go on in this picture, despite the flag. Cemeteries do not usually express Life.', '2003-09-22 06:55:52.000000', NULL, 1),
(425651, 38039, 12408, '<td valign="top">Granny and the new grandchild are well shot - and there is a sense of pride in the Gran''s face - but why have they put that weird ribbon around the kid''s head?</td>', 'Granny and the new grandchild are well shot - and there is a sense of pride in the Gran''s face - but why have they put that weird ribbon around the kid''s head?', '2003-09-22 06:57:07.000000', NULL, 1),
(425652, 38028, 12408, '<td valign="top">Dreadful picture - underexposed and uninteresting - doesn''t belong anywhere but the Trash.</td>', 'Dreadful picture - underexposed and uninteresting - doesn''t belong anywhere but the Trash.', '2003-09-22 06:57:47.000000', NULL, 1),
(425653, 37695, 12408, '<td valign="top">Excellent! well lit and expressive picture of a Birthday Boy and his cake (I assume).</td>', 'Excellent! well lit and expressive picture of a Birthday Boy and his cake (I assume).', '2003-09-22 06:58:35.000000', NULL, 1),
(425655, 38000, 12408, '<td valign="top">Tough on the American who''s life this represents. So far as I can judge he has some dodgy looking stuff on the left, a (used?) condom next to his car keys and a pile of credit cards. But I guess this does express the theme of this challenge<br/></td>', 'Tough on the American who''s life this represents. So far as I can judge he has some dodgy looking stuff on the left, a (used?) condom next to his car keys and a pile of credit cards. But I guess this does express the theme of this challenge', '2003-09-22 07:00:28.000000', NULL, 1),
(425657, 38178, 12408, '<td valign="top">Now on first sight I thought this was Granny holding the Newborn''s hand - but no - on closer inspection the small hand is fully formed and the nails possibly manicured (the varnish on the older hand could have been improved). Good try, but tacky.</td>', 'Now on first sight I thought this was Granny holding the Newborn''s hand - but no - on closer inspection the small hand is fully formed and the nails possibly manicured (the varnish on the older hand could have been improved). Good try, but tacky.', '2003-09-22 07:02:00.000000', NULL, 1),
(425659, 38053, 12408, '<td valign="top">very well staged and shot - but again this hardly represents the theme of Life. Is the bare-chested blurred figure in the fgd running from the Law or what?</td>', 'very well staged and shot - but again this hardly represents the theme of Life. Is the bare-chested blurred figure in the fgd running from the Law or what?', '2003-09-22 07:03:08.000000', NULL, 1),
(425661, 37341, 12408, '<td valign="top">Not much Life in this poorly exposed shot.</td>', 'Not much Life in this poorly exposed shot.', '2003-09-22 07:03:37.000000', NULL, 1),
(425664, 37803, 11321, '<td valign="top">is that cat alive? it seems to be so alive :)<br/>i don''t know why but i like the picture - maybe it is the capture of "organised mess" of our lives :)<br/></td>', 'is that cat alive? it seems to be so alive :)i don''t know why but i like the picture - maybe it is the capture of "organised mess" of our lives :)', '2003-09-22 07:04:40.000000', NULL, 1),
(425665, 37791, 12408, '<td valign="top">No - this belongs to Sport or Cycling but not really to Life - and it''s very ordinary</td>', 'No - this belongs to Sport or Cycling but not really to Life - and it''s very ordinary', '2003-09-22 07:05:12.000000', NULL, 1),
(425666, 38019, 12408, '<td valign="top">I guess not - if it''s the Moon there is no life on it.</td>', 'I guess not - if it''s the Moon there is no life on it.', '2003-09-22 07:05:54.000000', NULL, 1),
(425667, 37313, 12408, '<td valign="top">Pretty shot of a cabin and river, but nothing special to recommend it</td>', 'Pretty shot of a cabin and river, but nothing special to recommend it', '2003-09-22 07:06:27.000000', NULL, 1),
(425669, 37971, 12408, '<td valign="top">Good stoned shot - certainlly not to be taken seriously - but technically very interesting.</td>', 'Good stoned shot - certainlly not to be taken seriously - but technically very interesting.', '2003-09-22 07:07:16.000000', NULL, 1),
(425670, 37761, 12408, '<td valign="top">Nice shot of a pack of horses - but with no special point of view are technically uninspired.</td>', 'Nice shot of a pack of horses - but with no special point of view are technically uninspired.', '2003-09-22 07:07:56.000000', NULL, 1),
(425671, 37721, 12408, '<td valign="top">Some dull looking flowers on a white table-top do not express Life to me.</td>', 'Some dull looking flowers on a white table-top do not express Life to me.', '2003-09-22 07:08:37.000000', NULL, 1),
(425673, 38162, 12408, '<td valign="top">A good effort - not quite sure what it means (though the DVD of an obscure movie, FRAIL) does spell it out. The person watches too much tv and drinks coke and smokes so (she or he) not long for this world</td>', 'A good effort - not quite sure what it means (though the DVD of an obscure movie, FRAIL) does spell it out. The person watches too much tv and drinks coke and smokes so (she or he) not long for this world', '2003-09-22 07:10:34.000000', NULL, 1),
(425674, 38168, 12408, '<td valign="top">I liked this a lot - good idea, well shot and posed. It does represent a boy''s life too so is thematically correct.</td>', 'I liked this a lot - good idea, well shot and posed. It does represent a boy''s life too so is thematically correct.', '2003-09-22 07:11:31.000000', NULL, 1),
(425675, 37498, 12408, '<td valign="top">Yes, they do look happy and are clearly friendly. Well shot too with all the participants smiling - their dentist might like to have this one in his office.</td>', 'Yes, they do look happy and are clearly friendly. Well shot too with all the participants smiling - their dentist might like to have this one in his office.', '2003-09-22 07:12:42.000000', NULL, 1),
(425676, 37631, 12408, '<td valign="top">Sorry love, but the butterfly is too soft for my taste - maybe try the Unsharp filter?</td>', 'Sorry love, but the butterfly is too soft for my taste - maybe try the Unsharp filter?', '2003-09-22 07:13:27.000000', NULL, 1),
(425678, 38135, 12408, '<td valign="top">Excellent baby shot - and still in the hospital? of course the little creature could be more Lively, but it''s easier to snap a baby asleep.</td>', 'Excellent baby shot - and still in the hospital? of course the little creature could be more Lively, but it''s easier to snap a baby asleep.', '2003-09-22 07:14:51.000000', NULL, 1),
(425679, 37636, 12408, '<td valign="top">way to go Shiva - well lit and lively - would look good on the hood of a car!</td>', 'way to go Shiva - well lit and lively - would look good on the hood of a car!', '2003-09-22 07:19:38.000000', NULL, 1),
(425680, 38064, 12408, '<td valign="top">Not too interesting either as a subject or as a photograph.</td>', 'Not too interesting either as a subject or as a photograph.', '2003-09-22 07:20:12.000000', NULL, 1),
(425681, 37747, 12408, '<td valign="top">Superb - what else can one say - the picture is a winner all round. It really belongs in the Bird challenge, but we''ll draw a veil over that! Congratulations - you get my highest vote.</td>', 'Superb - what else can one say - the picture is a winner all round. It really belongs in the Bird challenge, but we''ll draw a veil over that! Congratulations - you get my highest vote.', '2003-09-22 07:21:28.000000', NULL, 1),
(425683, 37529, 12408, '<td valign="top">Good shot of this old Indian chap -</td>', 'Good shot of this old Indian chap -', '2003-09-22 07:22:33.000000', NULL, 1),
(425684, 38194, 12408, '<td valign="top">Idea is good but the shot is not too well done - a hard-shadowed flash is no help either.</td>', 'Idea is good but the shot is not too well done - a hard-shadowed flash is no help either.', '2003-09-22 07:23:23.000000', NULL, 1),
(425686, 37968, 12408, '<td valign="top">Very good table-top image - not really belonging to the theme of Life, but I guess a dead bishop does sort of fit the bill.</td>', 'Very good table-top image - not really belonging to the theme of Life, but I guess a dead bishop does sort of fit the bill.', '2003-09-22 07:24:25.000000', NULL, 1),
(425688, 37651, 12408, '<td valign="top">An OK shot of a waterfall (pity about the tree getting in the way) and good use of the slow shutter speed</td>', 'An OK shot of a waterfall (pity about the tree getting in the way) and good use of the slow shutter speed', '2003-09-22 07:25:20.000000', NULL, 1),
(425690, 37658, 12408, '<td valign="top">Life is fairly dull for a lot of people and waiting for the bus is one of the dullest moments of the day.</td>', 'Life is fairly dull for a lot of people and waiting for the bus is one of the dullest moments of the day.', '2003-09-22 07:26:02.000000', NULL, 1),
(425691, 37250, 12408, '<td valign="top">Good snap of the flower against a setting sun - and I guess the subject does just fit the challenge.</td>', 'Good snap of the flower against a setting sun - and I guess the subject does just fit the challenge.', '2003-09-22 07:26:48.000000', NULL, 1),
(425693, 37740, 12408, '<td valign="top">Very messy shot of the pooch (at least there is no red eye) with flowers over lit by the flash.</td>', 'Very messy shot of the pooch (at least there is no red eye) with flowers over lit by the flash.', '2003-09-22 07:28:08.000000', NULL, 1),
(425696, 37833, 12408, '<td valign="top">Very fine flower shot indeed - technically excellent</td>', 'Very fine flower shot indeed - technically excellent', '2003-09-22 07:30:01.000000', NULL, 1),
(425699, 37892, 12408, '<td valign="top">Your macro is pretty good to get so close to the ant - and sharp as a tack!</td>', 'Your macro is pretty good to get so close to the ant - and sharp as a tack!', '2003-09-22 07:31:28.000000', NULL, 1),
(425704, 38008, 12408, '<td valign="top">I wish this was just a teeny-tiny bit sharper - it''s good but not greatj</td>', 'I wish this was just a teeny-tiny bit sharper - it''s good but not greatj', '2003-09-22 07:44:38.000000', NULL, 1),
(425705, 38120, 12408, '<td valign="top">well caught!</td>', 'well caught!', '2003-09-22 07:44:55.000000', NULL, 1),
(425706, 37754, 12408, '<td valign="top">nice one - could be used for an ad - the long shadow (added?) makes the picture.</td>', 'nice one - could be used for an ad - the long shadow (added?) makes the picture.', '2003-09-22 07:45:44.000000', NULL, 1),
(425707, 37753, 12408, '<td valign="top">Very fine black &amp; white - good lighting - subject''s a bit depressing - maybe he''s regretting the latest tattoo?</td>', 'Very fine black & white - good lighting - subject''s a bit depressing - maybe he''s regretting the latest tattoo?', '2003-09-22 07:47:07.000000', NULL, 1),
(425708, 38014, 12408, '<td valign="top">Gosh - what a stunner! this bee is so well defined - highest marks!</td>', 'Gosh - what a stunner! this bee is so well defined - highest marks!', '2003-09-22 07:48:18.000000', NULL, 1),
(425709, 37798, 12408, '<td valign="top">Sure I''ve seen this bird before on  one of the other pictures in this batch - at it was a better shot.</td>', 'Sure I''ve seen this bird before on  one of the other pictures in this batch - at it was a better shot.', '2003-09-22 07:49:13.000000', NULL, 1),
(425710, 38173, 12408, '<td valign="top">This is not exactly sharp, but it doesn''t really matter. The feeling is good though whether it really fits the challenge is another matter</td>', 'This is not exactly sharp, but it doesn''t really matter. The feeling is good though whether it really fits the challenge is another matter', '2003-09-22 07:50:23.000000', NULL, 1),
(425712, 37271, 12408, '<td valign="top">Lots of life here! the falling objects are well caught and I like the mis-framed head.</td>', 'Lots of life here! the falling objects are well caught and I like the mis-framed head.', '2003-09-22 07:51:12.000000', NULL, 1),
(425713, 38193, 12408, '<td valign="top">Supercat! lovely definition - hardly fits the challenge but a great shot.</td>', 'Supercat! lovely definition - hardly fits the challenge but a great shot.', '2003-09-22 07:52:23.000000', NULL, 1),
