INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(431828, 38082, 472, '<td valign="top">very original. me like :-D</td>', 'very original. me like :-D', '2003-09-26 17:59:30.000000', NULL, 0),
(431829, 38065, 472, '<td valign="top">a top shot. good expression. kickass detail and color</td>', 'a top shot. good expression. kickass detail and color', '2003-09-26 18:00:02.000000', NULL, 0),
(432067, 37927, 11800, '<td valign="top">I gave this one a 9. Really loved all their expressions, the composition, and the whole goofy youthful feeling.  Most of all, I like the level you took this at. btw, I didn''t notice the border till now.  Guess it blends in good.</td>', 'I gave this one a 9. Really loved all their expressions, the composition, and the whole goofy youthful feeling.  Most of all, I like the level you took this at. btw, I didn''t notice the border till now.  Guess it blends in good.', '2003-09-26 23:32:31.000000', NULL, 0),
(432078, 37529, 11800, '<td valign="top">The title makes me think about how we label people instead of the man thinking about who he is.  I gave it a 9 because, even with it''s faults (overexposed,washed out) it did make me stop and think, and that''s not an easy thing to do. Good job.</td>', 'The title makes me think about how we label people instead of the man thinking about who he is.  I gave it a 9 because, even with it''s faults (overexposed,washed out) it did make me stop and think, and that''s not an easy thing to do. Good job.', '2003-09-26 23:52:22.000000', NULL, 0),
(432081, 38020, 11800, '<td valign="top">Thanks for the "how to" on the picture. I have to admit that I gave it a 5 because I didn''t know how it was done and I didn''t want to use the dq option. Sorry.  You really did go to a lot of work, and I wish I had given it a better score.</td>', 'Thanks for the "how to" on the picture. I have to admit that I gave it a 5 because I didn''t know how it was done and I didn''t want to use the dq option. Sorry.  You really did go to a lot of work, and I wish I had given it a better score.', '2003-09-27 00:03:10.000000', NULL, 0),
(432087, 37295, 11800, '<td valign="top">I gave this one an 8.  The border didn''t cause the score to be lower, there were just some very good photos in the contest and some were better than this one.  I like it. When I looked at it the first time, I thought, oh, two peas in a pod. How they are sitting so close to each other suggests they are very intimate, they are almost crowded into the space. They must like each other a lot to be that close.  The symetry works wonderfully also.  <br/>As far as the comments go, you would only be doing yourself a favor if you pay attention.  People don''t waste their time to be nasty.  They, perhaps, want to be able to help you improve your skills.  Try out the things they suggest instead of being defensive. The frame does look awkward.</td>', 'I gave this one an 8.  The border didn''t cause the score to be lower, there were just some very good photos in the contest and some were better than this one.  I like it. When I looked at it the first time, I thought, oh, two peas in a pod. How they are sitting so close to each other suggests they are very intimate, they are almost crowded into the space. They must like each other a lot to be that close.  The symetry works wonderfully also.  As far as the comments go, you would only be doing yourself a favor if you pay attention.  People don''t waste their time to be nasty.  They, perhaps, want to be able to help you improve your skills.  Try out the things they suggest instead of being defensive. The frame does look awkward.', '2003-09-27 00:22:20.000000', NULL, 0),
(432091, 37530, 9932, '<td valign="top">Excellent work! great contrast and colors.<br/>Now can you tell us how it was done and what equipment was used?<br/> <br/>Calvus</td>', 'Excellent work! great contrast and colors.Now can you tell us how it was done and what equipment was used? Calvus', '2003-09-27 00:30:09.000000', NULL, 0),
(432435, 38178, 12131, '<td valign="top">Sorry I missed this challenge.  This is such a great shot. There seems to be a lot of new life happening these days.  I wonder if it''s an epidemic.  Beautiful picture.</td>', 'Sorry I missed this challenge.  This is such a great shot. There seems to be a lot of new life happening these days.  I wonder if it''s an epidemic.  Beautiful picture.', '2003-09-27 13:47:33.000000', NULL, 0),
(432454, 38040, 5728, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by magnetic9999:</b></div><hr/><i>hey man you submitted this from russia!?!?</i></td></tr></table> <br/> <br/>Yup, took a long time too, the connections in Russia are very slow and it took something like 10 minutes to upload it!<br/> <br/>La-luna, I think it doesn''t matter how good a pic is in the open challenge you''ll always get one''s and two''s. That''s life :-)<br/> <br/>Thanx for all your comments everyone.</td>', 'Originally posted by magnetic9999:hey man you submitted this from russia!?!?  Yup, took a long time too, the connections in Russia are very slow and it took something like 10 minutes to upload it! La-luna, I think it doesn''t matter how good a pic is in the open challenge you''ll always get one''s and two''s. That''s life :-) Thanx for all your comments everyone.', '2003-09-27 14:06:30.000000', NULL, 0),
